// Pack pkg/dev-extension/agent-seed/ into agent-seed.generated.ts.
//
// The seed is what a review or a fix agent needs that the Studio's agent pod does not have:
// the skills the harness wrote (/my-pr-full-review, /my-dependabot-review, ...) and the rules
// they lean on. Bundled into the extension as strings, and written into the agent pod's home
// the first time an action needs them (see agent-tools.ts), because the pod has no image to
// bake them into and this extension is the only thing that knows about them.
//
//   node scripts/gen-agent-seed.mjs
//
// The generated file is committed, so ordinary builds never run this.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(here, '..', 'pkg', 'dev-extension', 'agent-seed');
const OUT = path.join(here, '..', 'pkg', 'dev-extension', 'agent-seed.generated.ts');

function walk(dir, prefix = '') {
  const out = {};

  for (const entry of fs.readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const rel = prefix ? `${ prefix }/${ entry.name }` : entry.name;

    if (entry.isDirectory()) {
      Object.assign(out, walk(path.join(dir, entry.name), rel));
    } else {
      out[rel] = fs.readFileSync(path.join(dir, entry.name), 'utf8');
    }
  }

  return out;
}

const files = walk(ROOT);
const body = Object.entries(files)
  .map(([rel, text]) => `  ${ JSON.stringify(rel) }: ${ JSON.stringify(text) },`)
  .join('\n');

fs.writeFileSync(OUT, `// Generated by scripts/gen-agent-seed.mjs from pkg/dev-extension/agent-seed/. Do not edit.
/* eslint-disable */
export const AGENT_SEED: Record<string, string> = {
${ body }
};
`);
console.log(`agent seed: ${ Object.keys(files).length } files, ${ (JSON.stringify(files).length / 1024).toFixed(1) } KiB -> ${ path.relative(process.cwd(), OUT) }`);
